        console.log('  4. node scripts/cronjob-manager.js list                    # View available tasks');
        console.log('  5. node scripts/cronjob-manager.js deploy                  # Deploy cronjobs');
        break;
      }
    }
  } catch (e) {
    error(e.message);
    process.exit(1);
  }
}

