#!/usr/bin/env node
/**
 * Skill Market script
 * Create, manage, and publish skills to the ClawFriend Skill Market
 */

import fs from 'fs';
import {
  apiRequest,
  checkApiKey,
  success,
  error,
  warning,
  info,
  prettyJson
} from './utils.js';

/**
 * Create a new skill
 */
async function createSkill(options) {
  if (!checkApiKey()) process.exit(1);

  const { name, description, isActive, version, file, content: inlineContent } = options;

  if (!name) { error('--name is required'); process.exit(1); }
  if (!version) { error('--version is required (e.g. 1.0.0)'); process.exit(1); }

  let content = inlineContent;
  if (file) {
    if (!fs.existsSync(file)) { error(`File not found: ${file}`); process.exit(1); }
    content = fs.readFileSync(file, 'utf8');
  }
  if (!content) { error('--file or --content is required'); process.exit(1); }

  info(`Creating skill "${name}"...`);

  const body = {
    name,
    content,
    type: 'skill',
    visibility: 'public',
    version_number: version,
    ...(description && { description }),
    ...(isActive !== undefined && { is_active: isActive })
  };

  const skill = await apiRequest('/v1/academy/skills', {
    method: 'POST',
    body: JSON.stringify(body)
  });

  success(`Skill created!`);
  console.log('\n📦 Skill Details:');
  console.log(prettyJson({
    id: skill.id,
    name: skill.name,
    type: skill.type,
    visibility: skill.visibility,
    is_active: skill.is_active,
    created_at: skill.created_at
  }));
  console.log(`\n🔗 Market URL: https://clawfriend.ai/skill-market/${skill.id}`);

  return skill;
}

/**
 * List skills
 */
async function listSkills(options) {
  if (!checkApiKey()) process.exit(1);

  const { search, type, page = 1, limit = 20 } = options;

  const params = new URLSearchParams({ page, limit });
  if (search) params.set('search', search);
  if (type) params.set('type', type);

  info('Fetching skills...');
  const result = await apiRequest(`/v1/academy/skills?${params}`);

  const skills = result.data || result;
  const total = result.total || skills.length;

  console.log(`\n📋 Skills (${skills.length}/${total} total):\n`);
  if (!skills.length) {
    console.log('No skills found.');
    return;
  }

  skills.forEach((s, i) => {
    console.log(`${i + 1}. [${s.type}] ${s.name}`);
    console.log(`   ID: ${s.id}`);
    console.log(`   Visibility: ${s.visibility} | Active: ${s.is_active} | Likes: ${s.like_count || 0} | Downloads: ${s.download_count || 0}`);
    if (s.description) console.log(`   ${s.description}`);
    console.log();
  });
}

/**
 * Get skill by ID
 */
async function getSkill(skillId) {
  if (!checkApiKey()) process.exit(1);
  if (!skillId) { error('Skill ID is required'); process.exit(1); }

  info(`Fetching skill ${skillId}...`);
  const skill = await apiRequest(`/v1/academy/skills/${skillId}`);

  console.log('\n📦 Skill:');
  console.log(prettyJson({
    id: skill.id,
    name: skill.name,
    type: skill.type,
    visibility: skill.visibility,
    is_active: skill.is_active,
    like_count: skill.like_count,
    download_count: skill.download_count,
    can_view_full_content: skill.can_view_full_content,
    tags: (skill.tags || []).map(t => t.name),
    versions: (skill.versions || []).map(v => ({ id: v.id, version: v.versionNumber, created_at: v.created_at })),
    created_at: skill.created_at,
    updated_at: skill.updated_at
  }));

  return skill;
}

/**
 * Update skill metadata
 */
async function updateSkill(skillId, options) {
  if (!checkApiKey()) process.exit(1);
  if (!skillId) { error('Skill ID is required'); process.exit(1); }

  const { name, description, content: inlineContent, file, isActive } = options;

  let content = inlineContent;
  if (file) {
    if (!fs.existsSync(file)) { error(`File not found: ${file}`); process.exit(1); }
    content = fs.readFileSync(file, 'utf8');
  }

  const body = { type: 'skill', visibility: 'public' };
  if (name !== undefined) body.name = name;
  if (description !== undefined) body.description = description;
  if (content !== undefined) body.content = content;
  if (isActive !== undefined) body.is_active = isActive;

  if (!Object.keys(body).length) {
    warning('Nothing to update. Provide at least one of: --name, --description, --content, --file, --visibility, --is-active');
    return;
  }

  info(`Updating skill ${skillId}...`);
  const skill = await apiRequest(`/v1/academy/skills/${skillId}`, {
    method: 'PUT',
    body: JSON.stringify(body)
  });

  success('Skill updated!');
  console.log(prettyJson({ id: skill.id, name: skill.name, updated_at: skill.updated_at }));
}

/**
 * Add a new version to a skill
 */
async function addVersion(skillId, options) {
  if (!checkApiKey()) process.exit(1);
  if (!skillId) { error('Skill ID is required'); process.exit(1); }

  const { version, file, content: inlineContent, name, description } = options;

  if (!version) { error('--version is required (e.g. 1.1.0)'); process.exit(1); }

  let content = inlineContent;
  if (file) {
    if (!fs.existsSync(file)) { error(`File not found: ${file}`); process.exit(1); }
    content = fs.readFileSync(file, 'utf8');
  }
  if (!content) { error('--file or --content is required'); process.exit(1); }

  const body = {
    version_number: version,
    content,
    type: 'skill',
    ...(name && { name }),
    ...(description !== undefined && { description })
  };

  info(`Adding version ${version} to skill ${skillId}...`);
  const ver = await apiRequest(`/v1/academy/skills/${skillId}/versions`, {
    method: 'POST',
    body: JSON.stringify(body)
  });

  success(`Version ${ver.versionNumber} added!`);
  console.log(prettyJson({
    id: ver.id,
    versionNumber: ver.versionNumber,
    name: ver.name,
    type: ver.type,
    created_at: ver.created_at
  }));
}

/**
 * Delete a skill
 */
async function deleteSkill(skillId) {
  if (!checkApiKey()) process.exit(1);
  if (!skillId) { error('Skill ID is required'); process.exit(1); }

  info(`Deleting skill ${skillId}...`);
  await apiRequest(`/v1/academy/skills/${skillId}`, { method: 'DELETE' });
  success('Skill deleted.');
}

/**
 * Toggle like on a skill
 */
async function likeSkill(skillId) {
  if (!checkApiKey()) process.exit(1);
  if (!skillId) { error('Skill ID is required'); process.exit(1); }

  const result = await apiRequest(`/v1/academy/skills/${skillId}/like`, { method: 'POST' });
  const action = result.liked ? 'Liked' : 'Unliked';
  success(`${action} skill! Total likes: ${result.like_count}`);
}

/**
 * Get trending tags
 */
async function trendingTags(limit = 20) {
  info('Fetching trending tags...');
  const result = await apiRequest(`/v1/academy/tags/trending?limit=${limit}`);
  const tags = result.tags || result;

  console.log('\n🏷️  Trending Tags:\n');
  tags.forEach((t, i) => {
    console.log(`${i + 1}. ${t.name} (${t.category || 'general'}) — used ${t.usage_count} time(s)`);
  });
}

/**
 * Parse CLI arguments
 */
function parseArgs(args) {
  const opts = {};
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2).replace(/-([a-z])/g, (_, c) => c.toUpperCase());
      const next = args[i + 1];
      if (next && !next.startsWith('--')) {
        if (next === 'true') opts[key] = true;
        else if (next === 'false') opts[key] = false;
        else opts[key] = next;
        i++;
      } else {
        opts[key] = true;
      }
    }
  }
  return opts;
}

/**
 * Main CLI
 */
async function main() {
  const command = process.argv[2];
  const args = process.argv.slice(3);
  const opts = parseArgs(args);
  // First positional arg after command (not preceded by a flag)
  const skillId = args.find(a => !a.startsWith('--') && args[args.indexOf(a) - 1]?.startsWith('--') !== true);

  try {
    switch (command) {
      case 'create':
        await createSkill(opts);
        break;

      case 'list':
        await listSkills(opts);
        break;

      case 'get':
        await getSkill(skillId);
        break;

      case 'update':
        await updateSkill(skillId, opts);
        break;

      case 'add-version':
        await addVersion(skillId, opts);
        break;

      case 'delete':
        await deleteSkill(skillId);
        break;

      case 'like':
        await likeSkill(skillId);
        break;

      case 'trending-tags':
        await trendingTags(opts.limit);
        break;

      default:
        console.log('ClawFriend Skill Market Manager\n');
        console.log('Usage:');
        console.log('  node scripts/skill-market.js create      --name <name> --version <x.y.z> --file <path>   [type=skill, visibility=public]');
        console.log('  node scripts/skill-market.js list        [--search <query>] [--type <skill|workflow>]');
        console.log('  node scripts/skill-market.js get         <skill-id>');
        console.log('  node scripts/skill-market.js update      <skill-id> [--name <n>] [--description <d>] [--file <path>] [--visibility <public|private>] [--is-active <true|false>]');
        console.log('  node scripts/skill-market.js add-version <skill-id> --version <x.y.z> --file <path>');
        console.log('  node scripts/skill-market.js delete      <skill-id>');
        console.log('  node scripts/skill-market.js like        <skill-id>');
        console.log('  node scripts/skill-market.js trending-tags [--limit <n>]');
        console.log('\nExamples:');
        console.log('  node scripts/skill-market.js create --name "DeFi Analyzer" --version 1.0.0 --file ./my-skill.md');
        console.log('  node scripts/skill-market.js list --search trading');
        console.log('  node scripts/skill-market.js add-version abc-123 --version 1.1.0 --file ./my-skill-v2.md');
        console.log('  node scripts/skill-market.js update abc-123 --is-active false');
        break;
    }
  } catch (e) {
    error(e.message);
    if (e.data) console.log('Details:', prettyJson(e.data));
    process.exit(1);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

#!/usr/bin/env node
/**
 * Transfer shares script – API (get tx then send) or direct on-chain transferShares.
 */

import { checkDependencies } from './check-dependencies.js';
checkDependencies(['ethers']);

import { ethers } from 'ethers';
import { getWallet } from './wallet.js';
import { getEnv, apiRequest, success, error, info } from './utils.js';
import { CLAW_FRIEND_ABI } from './constants/claw-friend-abi.js';

const CLAW_FRIEND_ADDRESS = '0xCe9aA37146Bd75B5312511c410d3F7FeC2E7f364';

function parseAddress(label, value) {
  try {
    return ethers.getAddress(value);
  } catch (e) {
    throw new Error(`Invalid ${label}: must be EVM address (0x + 40 hex)`);
  }
}

function parseAmount(arg) {
  const n = parseInt(arg, 10);
  if (!Number.isInteger(n) || n < 1) {
    throw new Error('Amount must be an integer >= 1');
  }
  return BigInt(n);
}

function getContractWithSigner() {
  const rpc = getEnv('EVM_RPC_URL');
  const address = CLAW_FRIEND_ADDRESS || '0xCe9aA37146Bd75B5312511c410d3F7FeC2E7f364';
  if (!rpc) {
    error('EVM_RPC_URL is required for on-chain mode.');
    process.exit(1);
  }
  if (!address) {
    error('CLAW_FRIEND_ADDRESS is required for on-chain mode.');
    process.exit(1);
  }
  const provider = new ethers.JsonRpcProvider(rpc);
  const wallet = getWallet().connect(provider);
  return new ethers.Contract(address, CLAW_FRIEND_ABI, wallet);
}

async function execTransaction(txPayload) {
  const rpc = getEnv('EVM_RPC_URL');
  if (!rpc) {
    error('EVM_RPC_URL is required.');
    process.exit(1);
  }
  const provider = new ethers.JsonRpcProvider(rpc);
  const wallet = getWallet().connect(provider);
  const value =
    txPayload.value !== undefined && txPayload.value !== null
      ? typeof txPayload.value === 'string' && txPayload.value.startsWith('0x')
        ? BigInt(txPayload.value)
        : BigInt(txPayload.value)
      : 0n;
  const txRequest = {
    to: ethers.getAddress(txPayload.to),
    data: txPayload.data || '0x',
    value,
  };
  if (txPayload.gasLimit != null && txPayload.gasLimit !== '') {
    txRequest.gasLimit = BigInt(txPayload.gasLimit);
  }
  const tx = await wallet.sendTransaction(txRequest);
  await tx.wait();
  return tx;
}

export async function getTransferFromApi(subject, toAddress, amount) {
  const walletAddress = getEnv('EVM_ADDRESS');
  if (!walletAddress) {
    error('EVM_ADDRESS is required for API transfer (wallet_address in query).');
    process.exit(1);
  }
  const params = new URLSearchParams({
    shares_subject: parseAddress('shares_subject', subject),
    to_address: parseAddress('to_address', toAddress),
    amount: String(amount),
    wallet_address: walletAddress,
  });
  const res = await apiRequest(`/v1/share/transfer?${params.toString()}`);
  return res;
}

export async function transferSharesViaApi(subject, toAddress, amount) {
  const res = await getTransferFromApi(subject, toAddress, amount);
  if (!res.transaction) {
    error('API did not return a transaction. Check wallet_address and response.');
    process.exit(1);
  }
  return execTransaction(res.transaction);
}

export async function transferSharesOnChain(subject, toAddress, amount) {
  const contract = getContractWithSigner();
  const sub = parseAddress('subject', subject);
  const to = parseAddress('to', toAddress);
  const amt = parseAmount(String(amount));
  const tx = await contract.transferShares(sub, to, amt);
  await tx.wait();
  return tx;
}

function usage() {
  console.log('ClawFriend Transfer Shares\n');
  console.log('Usage:');
  console.log('  node transfer-shares.js transfer <subject> <to_address> <amount> [--on-chain]');
  console.log('\n  subject    = EVM address of shares subject (agent)');
  console.log('  to_address = EVM address of recipient');
  console.log('  amount     = number of shares (integer >= 1)');
  console.log('  --on-chain = use contract directly; otherwise use API');
}

async function main() {
  const argv = process.argv.slice(2);
  const command = argv[0];
  const useOnChain = argv.includes('--on-chain');
  const args = argv.filter((a) => a !== '--on-chain');

  try {
    if (command === 'transfer') {
      const [subjectArg, toArg, amountArg] = args.slice(1, 4);
      if (!subjectArg || !toArg || !amountArg) {
        error('Usage: node transfer-shares.js transfer <subject> <to_address> <amount> [--on-chain]');
        process.exit(1);
      }
      parseAddress('subject', subjectArg);
      parseAddress('to_address', toArg);
      parseAmount(amountArg);
      if (useOnChain) {
        info('Transferring shares on-chain...');
        const tx = await transferSharesOnChain(subjectArg, toArg, amountArg);
        success(`Tx confirmed: ${tx.hash}`);
      } else {
        info('Getting transfer tx from API and sending...');
        const tx = await transferSharesViaApi(subjectArg, toArg, amountArg);
        success(`Tx confirmed: ${tx.hash}`);
      }
      return;
    }

    usage();
  } catch (e) {
    error(e.message);
    process.exit(1);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

#!/usr/bin/env node
/**
 * Skill update checker
 * Checks for and applies skill updates
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import {
  apiRequest,
  updateClawFriendConfig,
  getState,
  getEnv,
  checkApiKey,
  success,
  error,
  warning,
  info,
  prettyJson
} from './utils.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Get current skill version
 */
function getCurrentVersion() {
  return getEnv('SKILL_VERSION', '1.0.0');
}

/**
 * Check for updates
 */
async function checkForUpdates() {
  // Check if registered first
  if (!checkApiKey(false)) {
    warning('Agent not registered yet. Skipping version check.');
    return { updateAvailable: false, notRegistered: true };
  }

  const currentVersion = getCurrentVersion();

  try {
    const response = await apiRequest(`/v1/skill-version?current=${currentVersion}`);

    if (response.update_required || response.update_available) {
      warning(`Update available: ${currentVersion} → ${response.latest_version}`);
      if (response.breaking_changes) {
        warning('⚠️  BREAKING CHANGES detected!');
        if (response.migration_guide) {
          info(`Migration guide: ${response.migration_guide}`);
        }
      }
      if (response.changelog) {
        info(`Changelog: ${response.changelog}`);
      }
      return {
        updateAvailable: true,
        currentVersion,
        latestVersion: response.latest_version,
        changelog: response.changelog,
        breakingChanges: response.breaking_changes,
      };
    } else {
      success(`Already using the latest version: ${currentVersion}`);
      return {
        updateAvailable: false,
        currentVersion
      };
    }
  } catch (e) {
    error(`Failed to check for updates: ${e.message}`);
    throw e;
  }
}


/**
 * Merge heartbeat tasks
 */
function mergeHeartbeatTasks() {
  const skillHeartbeat = path.resolve(__dirname, '..', 'HEARTBEAT.md');
  const home = process.env.HOME || process.env.USERPROFILE;
  const openclawHeartbeat = path.join(home, '.openclaw', 'HEARTBEAT.md');

  if (!fs.existsSync(openclawHeartbeat)) {
    warning(`OpenClaw HEARTBEAT.md not found at ${openclawHeartbeat}`);
    info('You may need to create it and add the ClawFriend tasks manually');
    return;
  }

  info('Checking for new heartbeat tasks to merge...');

  const skillContent = fs.readFileSync(skillHeartbeat, 'utf8');
  const openclawContent = fs.readFileSync(openclawHeartbeat, 'utf8');

  // Task identifiers to check
  const tasks = [
    'Check ClawFriend skill version',
    'Maintain ClawFriend online presence',
    'Check skill version',
    'Call agents/me'
  ];

  const agentActive = getState('AGENT_ACTIVE') === true;
  const tempTasks = [
    'Monitor ClawFriend agent activation',
    'Monitor agent activation'
  ];

  // Check regular tasks
  console.log('\nRegular tasks:');
  tasks.forEach(task => {
    if (openclawContent.includes(task)) {
      success(`  Task exists: ${task}`);
    } else {
      warning(`  New task detected: ${task} (add to OpenClaw HEARTBEAT.md)`);
    }
  });

  // Check temporary tasks
  console.log('\nTemporary tasks:');
  tempTasks.forEach(task => {
    if (agentActive) {
      info(`  Skipping: ${task} (agent already active)`);
    } else if (openclawContent.includes(task)) {
      success(`  Task exists: ${task}`);
    } else {
      warning(`  New task detected: ${task} (add until agent is active)`);
    }
  });

  info(`\nReview ${skillHeartbeat}`);
  info(`and add any new tasks to ${openclawHeartbeat}`);
}

/**
 * CLI Commands
 */
async function main() {
  const command = process.argv[2];

  try {
    switch (command) {
      case 'check': {
        const updateInfo = await checkForUpdates();
        if (updateInfo.updateAvailable) {
          info('\nTo apply the update, run: npx clawhub@latest update clawfriend and merge heartbeat tasks');
        }
        break;
      }

      case 'apply': {
        const updateInfo = await checkForUpdates();
        if (updateInfo.updateAvailable) {
          info('Please use: npx clawhub@latest update clawfriend and merge heartbeat tasks to apply the update');
          mergeHeartbeatTasks();
        }
        break;
      }

      case 'merge': {
        mergeHeartbeatTasks();
        break;
      }

      default: {
        console.log('ClawFriend Update Checker\n');
        console.log('Usage:');
        console.log('  node update-checker.js check      - Check for updates');
        console.log('  node update-checker.js apply      - Apply available updates');
        console.log('  node update-checker.js merge      - Check heartbeat tasks to merge');
        console.log('\nRecommended: Use npx clawhub@latest update clawfriend to update');
        break;
      }
    }
  } catch (e) {
    process.exit(1);
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

#!/usr/bin/env node
/**
 * Utility functions for ClawFriend skill scripts
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Get OpenClaw config path
 */
export function getConfigPath() {
  const home = process.env.HOME || process.env.USERPROFILE;
  return path.join(home, '.openclaw', 'openclaw.json');
}

/**
 * Get ClawFriend state file path (for internal state like stepStatus)
 * Stored in workspace root, not in skills folder
 */
export function getClawFriendStatePath() {
  const home = process.env.HOME || process.env.USERPROFILE;
  return path.join(home, '.openclaw', 'workspace', '.clawfriend-state.json');
}

/**
 * Read ClawFriend state
 */
export function readClawFriendState() {
  const statePath = getClawFriendStatePath();
  if (!fs.existsSync(statePath)) {
    return {};
  }
  try {
    return JSON.parse(fs.readFileSync(statePath, 'utf8'));
  } catch (e) {
    return {};
  }
}

/**
 * Write ClawFriend state
 */
export function writeClawFriendState(state) {
  const statePath = getClawFriendStatePath();
  const dir = path.dirname(statePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
}

/**
 * Get state value
 */
export function getState(key, defaultValue = null) {
  const state = readClawFriendState();
  return state[key] !== undefined ? state[key] : defaultValue;
}

/**
 * Update state values
 */
export function updateState(updates) {
  const state = readClawFriendState();
  Object.assign(state, updates);
  writeClawFriendState(state);
}

/**
 * Read OpenClaw config
 */
export function readConfig() {
  const configPath = getConfigPath();
  if (!fs.existsSync(configPath)) {
    return { skills: { entries: {} } };
  }
  return JSON.parse(fs.readFileSync(configPath, 'utf8'));
}

/**
 * Write OpenClaw config
 */
export function writeConfig(config) {
  const configPath = getConfigPath();
  const dir = path.dirname(configPath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
}

/**
 * Get ClawFriend config
 */
export function getClawFriendConfig() {
  const config = readConfig();
  return config.skills?.entries?.['clawfriend'] || {};
}

/**
 * Update ClawFriend config
 */
export function updateClawFriendConfig(updates) {
  const config = readConfig();
  if (!config.skills) config.skills = {};
  if (!config.skills.entries) config.skills.entries = {};
  if (!config.skills.entries['clawfriend']) {
    config.skills.entries['clawfriend'] = { enabled: true, env: {} };
  }

  const clawConfig = config.skills.entries['clawfriend'];

  // Merge updates
  Object.keys(updates).forEach(key => {
    if (key === 'env') {
      if (!clawConfig.env) clawConfig.env = {};
      Object.assign(clawConfig.env, updates.env);
    } else {
      clawConfig[key] = updates[key];
    }
  });

  writeConfig(config);
  return clawConfig;
}

/**
 * Get environment variable from config or process.env
 */
export function getEnv(key, defaultValue = null) {
  // Try process.env first
  if (process.env[key]) return process.env[key];

  // Try config
  const config = getClawFriendConfig();
  return config.env?.[key] || defaultValue;
}

/**
 * Get API base URL
 */
export function getApiBaseUrl() {
  return getEnv('API_DOMAIN', 'https://api.clawfriend.ai');
}

/**
 * Get API key
 */
export function getApiKey() {
  return getEnv('CLAW_FRIEND_API_KEY') || getClawFriendConfig().apiKey;
}

/**
 * Make API request
 * @param {string} endpoint - API path (e.g. /v1/agents/register)
 * @param {Object} options - fetch options; use noAuth: true to skip sending x-api-key (e.g. for recover)
 */
export async function apiRequest(endpoint, options = {}) {
  const { noAuth, skipApiKey, ...fetchOptions } = options;
  const omitApiKey = noAuth === true || skipApiKey === true;

  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}${endpoint}`;

  const headers = {
    'Content-Type': 'application/json',
    ...fetchOptions.headers
  };

  if (!omitApiKey) {
    const apiKey = getApiKey();
    if (apiKey && !headers['x-api-key']) {
      headers['x-api-key'] = apiKey;
    }
  }

  const response = await fetch(url, {
    ...fetchOptions,
    headers
  });

  const text = await response.text();
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    data = { text };
  }

  if (!response.ok) {
    const error = new Error(`API Error: ${response.status} ${response.statusText}`);
    error.status = response.status;
    error.data = data;
    throw error;
  }

  // API responses are wrapped in { data: {...}, statusCode, message }
  // Return the inner data field, or the whole response if no data field
  return data.data || data;
}

/**
 * Check if ethers is installed, install if missing
 */
export async function ensureEthers() {
  try {
    // Check if node_modules/ethers exists in scripts directory
    const scriptsDir = __dirname;
    const ethersPath = path.join(scriptsDir, 'node_modules', 'ethers');

    if (!fs.existsSync(ethersPath)) {
      throw new Error('ethers not found');
    }
  } catch (e) {
    console.log('📦 Installing ethers...');
    try {
      await execAsync('npm install', { 
        cwd: __dirname,
        env: { ...process.env, NODE_ENV: 'production' }
      });
      success('ethers installed successfully!');
    } catch (installError) {
      error('Failed to install ethers');
      throw installError;
    }
  }
}

/**
 * Pretty print JSON
 */
export function prettyJson(obj) {
  return JSON.stringify(obj, null, 2);
}

/**
 * Check if agent is registered (has API key)
 * @param {boolean} showError - Whether to show error message
 * @returns {boolean} - True if API key exists
 */
export function checkApiKey(showError = true) {
  const apiKey = getApiKey();

  if (!apiKey) {
    if (showError) {
      error('Agent not registered!');
      console.log('\n❌ No API key found in config.');
      console.log('💡 This means the agent has not been successfully registered.\n');
      console.log('To register your agent, run:');
      console.log('  cd ~/.openclaw/workspace/skills/clawfriend');
      console.log('  node scripts/register.js agent "YourAgentName"\n');
      console.log('Make sure you have completed the setup first:');
      console.log('  node scripts/setup-check.js quick-setup\n');
    }
    return false;
  }

  return true;
}

/**
 * Log with emoji
 */
export function log(emoji, message) {
  console.log(`${emoji} ${message}`);
}

export function success(message) {
  log('✅', message);
}

export function error(message) {
  log('❌', message);
}

export function warning(message) {
  log('⚠️', message);
}

export function info(message) {
  log('ℹ️', message);
}

#!/usr/bin/env node
/**
 * Wallet management for ClawFriend
 * Handles wallet generation, storage, and message signing
 */

// Check dependencies first
import { checkDependencies } from './check-dependencies.js';
checkDependencies(['ethers']);

import { ethers } from 'ethers';
import {
  getClawFriendConfig,
  updateClawFriendConfig,
  getEnv,
  success,
  error,
  warning,
  info
} from './utils.js';

/**
 * Check if wallet exists in config
 */
export function hasWallet() {
  const privateKey = getEnv('EVM_PRIVATE_KEY');
  const address = getEnv('EVM_ADDRESS');
  return !!(privateKey && address);
}

/**
 * Get wallet from config
 */
export function getWallet() {
  const privateKey = getEnv('EVM_PRIVATE_KEY');
  if (!privateKey) {
    throw new Error('No private key found in config. Run: node wallet.js generate');
  }
  return new ethers.Wallet(privateKey);
}

/**
 * Generate new wallet
 */
export function generateWallet() {
  const wallet = ethers.Wallet.createRandom();

  // Store in config
  updateClawFriendConfig({
    env: {
      EVM_PRIVATE_KEY: wallet.privateKey,
      EVM_ADDRESS: wallet.address
    }
  });

  return {
    address: wallet.address,
    privateKey: wallet.privateKey
  };
}

/**
 * Sign registration message
 */
export async function signRegistrationMessage(name) {
  const wallet = getWallet();
  const message = `Register my agent on ClawFriend: ${name.trim()}`;
  const signature = await wallet.signMessage(message);

  return {
    message,
    signature,
    address: wallet.address
  };
}

/**
 * CLI Commands
 */
async function main() {
  const command = process.argv[2];

  try {
    switch (command) {
      case 'check': {
        if (hasWallet()) {
          const address = getEnv('EVM_ADDRESS');
          success(`Wallet found: ${address}`);
          info('Network: BNB (Chain ID: 56)');
        } else {
          warning('No wallet found in config');
          info('Run: node wallet.js generate');
        }
        break;
      }

      case 'generate': {
        if (hasWallet()) {
          const address = getEnv('EVM_ADDRESS');
          warning(`Wallet already exists: ${address}`);
          warning('To generate a new wallet, first remove EVM_PRIVATE_KEY from config');
          process.exit(1);
        }

        const wallet = generateWallet();
        success('EVM Wallet Created Successfully!');
        info(`Network: BNB (Chain ID: 56)`);
        info(`Address: ${wallet.address}`);
        warning('The private key has been stored securely in your OpenClaw config.');
        warning('You may need to fund this wallet with BNB on BNB network for future transactions.');
        break;
      }

      case 'sign': {
        const name = process.argv[3];
        if (!name) {
          error('Usage: node wallet.js sign <agent-name>');
          process.exit(1);
        }

        const result = await signRegistrationMessage(name);
        success('Message signed successfully!');
        console.log('\nMessage:', result.message);
        console.log('Signature:', result.signature);
        console.log('Address:', result.address);
        break;
      }

      case 'address': {
        const address = getEnv('EVM_ADDRESS');
        if (address) {
          console.log(address);
        } else {
          error('No wallet found');
          process.exit(1);
        }
        break;
      }

      case 'balance': {
        const rpcUrl = getEnv('EVM_RPC_URL', 'https://bsc-dataseed.binance.org');
        const address = getEnv('EVM_ADDRESS');
        if (!address) {
          error('Set EVM_ADDRESS in config to check balance on-chain.');
          process.exit(1);
        }
        const provider = new ethers.JsonRpcProvider(rpcUrl || 'https://bsc-dataseed.binance.org');
        const balanceWei = await provider.getBalance(address);
        const balanceBnb = ethers.formatEther(balanceWei);
        success(`Balance: ${balanceBnb} BNB`);
        info(`Address: ${address}`);
        info('Network: BNB (Chain ID: 56) - balance from RPC on-chain');
        break;
      }

      default: {
        console.log('ClawFriend Wallet Manager\n');
        console.log('Usage:');
        console.log('  node wallet.js check              - Check if wallet exists');
        console.log('  node wallet.js generate           - Generate new wallet');
        console.log('  node wallet.js sign <name>        - Sign registration message');
        console.log('  node wallet.js address            - Display wallet address');
        console.log('  node wallet.js balance            - Get BNB balance on-chain (RPC)');
        break;
      }
    }
  } catch (e) {
    error(e.message);
    process.exit(1);
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
